/* OpenLearnHub - Global Styles */

:root {
  --primary-dark: #0A0A23;
  --accent-gold: #FEAC32;
  --link-blue: #002EAD;
  --text-primary: #1a1a2e;
  --text-secondary: #4a4a5a;
  --text-muted: #6b6b7b;
  --bg-white: #ffffff;
  --bg-light: #f5f5f7;
  --bg-card: #ffffff;
  --border-color: #e2e2e8;
  --tag-ai: #dcfce7;
  --tag-ai-text: #166534;
  --tag-web-scraping: #dbeafe;
  --tag-web-scraping-text: #1e40af;
  --tag-databases: #f3e8ff;
  --tag-databases-text: #6b21a8;
  --tag-elasticsearch: #fef3c7;
  --tag-elasticsearch-text: #92400e;
  --tag-data-engineering: #fce7f3;
  --tag-data-engineering-text: #9d174d;
  --tag-python: #e0f2fe;
  --tag-python-text: #075985;
  --tag-node-js: #dcfce7;
  --tag-node-js-text: #166534;
  --tag-google-sheets: #fef3c7;
  --tag-google-sheets-text: #92400e;
  --tag-general-programming: #f3f4f6;
  --tag-general-programming-text: #374151;
  --tag-javascript: #fef9c3;
  --tag-javascript-text: #854d0e;
  --tag-web-development: #dbeafe;
  --tag-web-development-text: #1e40af;
  --tag-react: #e0f2fe;
  --tag-react-text: #075985;
  --tag-tech: #f3e8ff;
  --tag-tech-text: #6b21a8;
  --tag-youtube: #fee2e2;
  --tag-youtube-text: #991b1b;
  --tag-startup: #fef3c7;
  --tag-startup-text: #92400e;
  --tag-software-development: #e0f2fe;
  --tag-software-development-text: #075985;
  --tag-design: #fce7f3;
  --tag-design-text: #9d174d;
  --tag-productivity: #dcfce7;
  --tag-productivity-text: #166534;
  --tag-life-lessons: #fef3c7;
  --tag-life-lessons-text: #92400e;
  --tag-css: #dbeafe;
  --tag-css-text: #1e40af;
  --tag-self-improvement: #f3e8ff;
  --tag-self-improvement-text: #6b21a8;
  --tag-ai-automation: #dcfce7;
  --tag-ai-automation-text: #166534;
  --radius: 0.5rem;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--text-primary);
  background-color: var(--bg-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

@media (min-width: 640px) {
  .container {
    padding: 0 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 2rem;
  }
}

/* Header */
.site-header {
  background-color: var(--primary-dark);
  color: white;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  gap: 1rem;
}

.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: white;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-gold);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 800;
  color: var(--primary-dark);
}

.search-bar {
  flex: 1;
  max-width: 400px;
  display: none;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  border: none;
  background: rgba(255,255,255,0.1);
  color: white;
  font-size: 0.875rem;
  outline: none;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.search-bar input:focus {
  background: rgba(255,255,255,0.15);
}

.desktop-nav {
  display: none;
  gap: 1.5rem;
}

.desktop-nav a {
  color: white;
  font-size: 0.9375rem;
  font-weight: 500;
  text-decoration: none;
  opacity: 0.9;
  transition: opacity 0.2s;
}

.desktop-nav a:hover {
  opacity: 1;
  text-decoration: underline;
}

.menu-toggle {
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  padding: 0.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mobile-nav {
  display: none;
  background: rgba(0,0,0,0.2);
  padding: 0.75rem 1rem;
  flex-direction: column;
  gap: 0.75rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  color: white;
  font-size: 0.9375rem;
  font-weight: 500;
  text-decoration: none;
  padding: 0.5rem 0;
}

@media (min-width: 768px) {
  .search-bar {
    display: block;
  }
  .desktop-nav {
    display: flex;
  }
  .menu-toggle {
    display: none;
  }
  .mobile-nav {
    display: none !important;
  }
}

/* Banner */
.site-banner {
  background: var(--bg-light);
  border-bottom: 1px solid var(--border-color);
  padding: 0.75rem 1rem;
  text-align: center;
}

.site-banner a {
  color: var(--text-primary);
  font-size: 0.9375rem;
  font-weight: 500;
  text-decoration: none;
}

.site-banner a:hover {
  text-decoration: underline;
}

/* Tag Styles */
.tag {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.025em;
  text-decoration: none;
}

.tag:hover {
  text-decoration: none;
  opacity: 0.85;
}

.tag-ai { background: var(--tag-ai); color: var(--tag-ai-text); }
.tag-web-scraping { background: var(--tag-web-scraping); color: var(--tag-web-scraping-text); }
.tag-databases { background: var(--tag-databases); color: var(--tag-databases-text); }
.tag-elasticsearch { background: var(--tag-elasticsearch); color: var(--tag-elasticsearch-text); }
.tag-data-engineering { background: var(--tag-data-engineering); color: var(--tag-data-engineering-text); }
.tag-python { background: var(--tag-python); color: var(--tag-python-text); }
.tag-node-js { background: var(--tag-node-js); color: var(--tag-node-js-text); }
.tag-google-sheets { background: var(--tag-google-sheets); color: var(--tag-google-sheets-text); }
.tag-general-programming { background: var(--tag-general-programming); color: var(--tag-general-programming-text); }
.tag-javascript { background: var(--tag-javascript); color: var(--tag-javascript-text); }
.tag-web-development { background: var(--tag-web-development); color: var(--tag-web-development-text); }
.tag-react { background: var(--tag-react); color: var(--tag-react-text); }
.tag-tech { background: var(--tag-tech); color: var(--tag-tech-text); }
.tag-youtube { background: var(--tag-youtube); color: var(--tag-youtube-text); }
.tag-startup { background: var(--tag-startup); color: var(--tag-startup-text); }
.tag-software-development { background: var(--tag-software-development); color: var(--tag-software-development-text); }
.tag-design { background: var(--tag-design); color: var(--tag-design-text); }
.tag-productivity { background: var(--tag-productivity); color: var(--tag-productivity-text); }
.tag-life-lessons { background: var(--tag-life-lessons); color: var(--tag-life-lessons-text); }
.tag-css { background: var(--tag-css); color: var(--tag-css-text); }
.tag-self-improvement { background: var(--tag-self-improvement); color: var(--tag-self-improvement-text); }
.tag-ai-automation { background: var(--tag-ai-automation); color: var(--tag-ai-automation-text); }

/* Article Cards */
.article-card {
  background: var(--bg-card);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border-color);
  transition: box-shadow 0.2s, transform 0.2s;
  display: flex;
  flex-direction: column;
}

.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.article-card .thumbnail {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background: var(--bg-light);
}

.article-card .card-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  flex: 1;
}

.article-card .card-title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-primary);
  text-decoration: none;
}

.article-card .card-title:hover {
  color: var(--link-blue);
  text-decoration: underline;
}

.article-card .card-meta {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  margin-top: auto;
}

.article-card .author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-light);
  object-fit: cover;
}

.article-card .author-name {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  font-weight: 500;
}

.article-card .timestamp {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Featured Article */
.featured-card {
  background: var(--bg-card);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border-color);
  display: grid;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .featured-card {
    grid-template-columns: 1.2fr 1fr;
  }
}

.featured-card .thumbnail-wrap {
  position: relative;
  overflow: hidden;
}

.featured-card .thumbnail {
  width: 100%;
  height: 100%;
  min-height: 240px;
  object-fit: cover;
  background: var(--bg-light);
}

.featured-card .tag-overlay {
  position: absolute;
  top: 1rem;
  left: 1rem;
}

.featured-card .featured-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1rem;
}

.featured-card .featured-title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-primary);
}

@media (min-width: 1024px) {
  .featured-card .featured-title {
    font-size: 1.75rem;
  }
}

.featured-card .featured-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Article Grid */
.article-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .article-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background 0.2s, transform 0.1s;
  text-decoration: none;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-primary:hover {
  background: #e59b2a;
  text-decoration: none;
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-color);
}

.btn-outline:hover {
  border-color: var(--text-muted);
  text-decoration: none;
}

.btn-dark {
  background: var(--primary-dark);
  color: white;
}

.btn-dark:hover {
  background: #14143a;
  text-decoration: none;
}

/* Load More */
.load-more-wrap {
  text-align: center;
  margin-top: 2.5rem;
}

/* Section Headers */
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--text-primary);
}

/* Footer */
.site-footer {
  background: var(--bg-light);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0 2rem;
  margin-top: 4rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr;
  }
}

.footer-mission {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 480px;
}

.footer-heading {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-links a {
  font-size: 0.875rem;
  color: var(--text-secondary);
  text-decoration: none;
}

.footer-links a:hover {
  color: var(--link-blue);
  text-decoration: underline;
}

.footer-bottom {
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Curriculum Page */
.cert-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .cert-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.cert-item {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--text-primary);
  font-weight: 500;
  transition: box-shadow 0.2s, border-color 0.2s;
}

.cert-item:hover {
  text-decoration: none;
  border-color: var(--accent-gold);
  box-shadow: var(--shadow);
}

.cert-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius);
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  flex-shrink: 0;
}

/* Donation Page */
.donation-tabs {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.donation-tab {
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius);
  border: 1.5px solid var(--border-color);
  background: white;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  color: var(--text-primary);
}

.donation-tab:hover {
  border-color: var(--accent-gold);
}

.donation-tab.active {
  background: var(--accent-gold);
  border-color: var(--accent-gold);
  color: var(--primary-dark);
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.125rem 0;
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-primary);
  cursor: pointer;
  text-align: left;
}

.faq-question:hover {
  color: var(--link-blue);
}

.faq-icon {
  width: 20px;
  height: 20px;
  transition: transform 0.3s;
  flex-shrink: 0;
  margin-left: 1rem;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
  padding-bottom: 1.125rem;
}

.faq-answer p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* Tag Page */
.tag-header {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1.5rem;
}

.tag-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.tag-header p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

.popular-tags {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.popular-tag-item {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.875rem;
  background: var(--bg-light);
  border-radius: 9999px;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
  transition: background 0.2s;
}

.popular-tag-item:hover {
  background: var(--border-color);
  text-decoration: none;
}

.popular-tag-item .count {
  color: var(--text-muted);
  font-weight: 400;
}

/* Stats / Achievements */
.stats-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-card {
  padding: 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
}

.stat-card h4 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  margin-bottom: 0.25rem;
}

.stat-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Initiatives */
.initiative-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.initiative-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.initiative-list .bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-gold);
  margin-top: 0.5rem;
  flex-shrink: 0;
}

/* Benefits */
.benefit-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.benefit-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.benefit-list .check {
  color: var(--accent-gold);
  font-weight: 700;
  flex-shrink: 0;
}

/* Utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.text-center { text-align: center; }
.mt-1 { margin-top: 0.25rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-3 { margin-top: 0.75rem; }
.mt-4 { margin-top: 1rem; }
.mt-6 { margin-top: 1.5rem; }
.mt-8 { margin-top: 2rem; }
.mt-12 { margin-top: 3rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.py-8 { padding-top: 2rem; padding-bottom: 2rem; }
.py-12 { padding-top: 3rem; padding-bottom: 3rem; }
.py-16 { padding-top: 4rem; padding-bottom: 4rem; }
.max-w-2xl { max-width: 42rem; }
.max-w-3xl { max-width: 48rem; }
.mx-auto { margin-left: auto; margin-right: auto; }
.bg-light { background: var(--bg-light); }
.rounded { border-radius: var(--radius); }

// OpenLearnHub - Global JavaScript

// Mobile menu toggle
document.addEventListener('DOMContentLoaded', function () {
  const menuToggle = document.getElementById('menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');

  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', function () {
      const isOpen = mobileNav.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(isOpen));
    });
  }
});

// Donation amount tabs
function initDonationTabs() {
  const tabs = document.querySelectorAll('.donation-tab');
  const description = document.getElementById('donation-description');
  const sublabel = document.getElementById('donation-sublabel');

  if (!tabs.length || !description || !sublabel) return;

  const amounts = {
    5: {
      text: 'Your $5 donation will provide 250 hours of learning to people around the world each month.',
      label: 'Donating $5 / month: edit amount · Secure donation'
    },
    10: {
      text: 'Your $10 donation will provide 500 hours of learning to people around the world each month.',
      label: 'Donating $10 / month: edit amount · Secure donation'
    },
    20: {
      text: 'Your $20 donation will provide 1,000 hours of learning to people around the world each month.',
      label: 'Donating $20 / month: edit amount · Secure donation'
    },
    40: {
      text: 'Your $40 donation will provide 2,000 hours of learning to people around the world each month.',
      label: 'Donating $40 / month: edit amount · Secure donation'
    }
  };

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      tabs.forEach(function (t) { t.classList.remove('active'); });
      tab.classList.add('active');
      const amount = parseInt(tab.dataset.amount, 10);
      const info = amounts[amount];
      if (info) {
        description.textContent = info.text;
        sublabel.textContent = info.label;
      }
    });
  });
}

// FAQ Accordion
function initFaqAccordion() {
  const items = document.querySelectorAll('.faq-item');

  items.forEach(function (item) {
    const question = item.querySelector('.faq-question');
    if (!question) return;

    question.addEventListener('click', function () {
      const isOpen = item.classList.contains('open');
      // Optional: close others
      // items.forEach(function (i) { i.classList.remove('open'); });
      item.classList.toggle('open', !isOpen);
    });
  });
}

